package ru.neverland.townycitizens.model;
import java.util.*;

/** A petition does not grant membership; an approval and its status are one immutable transition. */
public final class Admissions {
    private Admissions(){}
    public static final long DAY=86_400_000L;
    public enum Phase{OPEN,APPROVED,REJECTED,WITHDRAWN}
    public record Terms(int sponsors,int minimumDays,String text,long revision){
        public Terms{if(sponsors<0||sponsors>5||minimumDays<0||minimumDays>3650||text==null||text.isBlank()||text.length()>500||revision<0)throw new IllegalArgumentException("Неверные условия гражданства");}
        public static Terms defaults(){return new Terms(0,0,"Соблюдайте правила города.",0);}
    }
    public record Sponsor(UUID resident,String name,long at){public Sponsor{Objects.requireNonNull(resident);if(name==null||name.isBlank()||name.length()>80||at<0)throw new IllegalArgumentException("Неверное поручительство");}}
    public record Application(UUID id,UUID town,UUID applicant,String name,CitizenshipStatus desired,int days,int maximumDays,Terms terms,long registeredAt,String message,long created,Phase phase,Map<UUID,Sponsor> sponsors,UUID actor,String actorName,long decided,String reason,long revision){
        public Application{Objects.requireNonNull(id);Objects.requireNonNull(town);Objects.requireNonNull(applicant);Objects.requireNonNull(desired);Objects.requireNonNull(terms);Objects.requireNonNull(phase);sponsors=Map.copyOf(sponsors);if(name==null||name.isBlank()||name.length()>80||desired==CitizenshipStatus.FOREIGNER||maximumDays<1||maximumDays>3650||(desired==CitizenshipStatus.TEMPORARY?(days<1||days>maximumDays):days!=0)||registeredAt<0||message==null||message.isBlank()||message.length()>500||created<0||sponsors.size()>32||actorName==null||actorName.length()>80||reason==null||reason.length()>240||revision<1)throw new IllegalArgumentException("Некорректное заявление");for(var e:sponsors.entrySet())if(!e.getKey().equals(e.getValue().resident())||e.getKey().equals(applicant))throw new IllegalArgumentException("Неверный поручитель");if(phase==Phase.OPEN?(actor!=null||!actorName.isEmpty()||decided!=0||!reason.isEmpty()):(actor==null||actorName.isBlank()||decided<created))throw new IllegalArgumentException("Некорректное решение");}
        public Application support(Map<UUID,Sponsor> next){if(phase!=Phase.OPEN)throw new IllegalArgumentException("Заявление уже рассмотрено");return new Application(id,town,applicant,name,desired,days,maximumDays,terms,registeredAt,message,created,phase,next,null,"",0,"",Math.incrementExact(revision));}
        public Application close(Phase next,UUID who,String whoName,String why,long now){if(phase!=Phase.OPEN||next==Phase.OPEN)throw new IllegalArgumentException("Заявление уже рассмотрено");return new Application(id,town,applicant,name,desired,days,maximumDays,terms,registeredAt,message,created,next,sponsors,who,whoName,now,why,Math.incrementExact(revision));}
    }
    public record Change(UUID id,UUID town,UUID resident,String before,String after,UUID actor,String actorName,long at,String reason,UUID application){
        public Change{Objects.requireNonNull(id);Objects.requireNonNull(town);Objects.requireNonNull(resident);if(!"DEFAULT".equals(before))CitizenshipStatus.valueOf(before);CitizenshipStatus.valueOf(after);if(actorName==null||actorName.isBlank()||actorName.length()>80||at<0||reason==null||reason.length()>240)throw new IllegalArgumentException("Неверная история гражданства");}
    }
    public record Board(Map<UUID,Terms> policies,Map<UUID,Application> applications,List<Change> history,long revision){
        public Board{policies=Map.copyOf(policies);applications=Map.copyOf(applications);history=List.copyOf(history);if(policies.size()>10000||applications.size()>10000||history.size()>10000||revision<0)throw new IllegalArgumentException("Достигнут предел реестра заявлений; требуется архивирование");var open=new HashSet<String>();for(var e:applications.entrySet()){var a=e.getValue();if(!e.getKey().equals(a.id())||a.phase()==Phase.OPEN&&!open.add(a.town()+"/"+a.applicant()))throw new IllegalArgumentException("Повтор открытого заявления");}var ids=new HashSet<UUID>();for(var h:history)if(!ids.add(h.id()))throw new IllegalArgumentException("Повтор записи истории");}
        public static Board empty(){return new Board(Map.of(),Map.of(),List.of(),0);}
        public Terms terms(UUID town){return policies.getOrDefault(town,Terms.defaults());}
    }
    public record State(Map<String,CitizenshipRecord> records,Board board){
        public State{records=Map.copyOf(records);Objects.requireNonNull(board);for(var e:records.entrySet())if(!e.getKey().equals(e.getValue().key()))throw new IllegalArgumentException("ID гражданства не совпадает");for(var a:board.applications().values())if(a.phase()==Phase.APPROVED&&!records.containsKey(a.town()+"/"+a.applicant()))throw new IllegalArgumentException("Одобрение без записи гражданства");}
        public static State empty(){return new State(Map.of(),Board.empty());}
        public CitizenshipRecord record(UUID town,UUID resident){return records.get(town+"/"+resident);}
    }
    private static State change(State old,Map<String,CitizenshipRecord> records,Map<UUID,Terms> policies,Map<UUID,Application> apps,List<Change> history){return new State(records,new Board(policies,apps,history,Math.incrementExact(old.board().revision())));}
    public static State policy(State state,UUID town,Terms next,long expected){var old=state.board().terms(town);if(old.revision()!=expected||next.revision()!=expected+1)throw new IllegalArgumentException("Условия изменились. Откройте их заново");var policies=new HashMap<>(state.board().policies());policies.put(town,next);return change(state,state.records(),policies,state.board().applications(),state.board().history());}
    public static State submit(State state,Application app){var prior=state.board().applications().get(app.id());if(prior!=null){if(prior.equals(app))return state;throw new IllegalArgumentException("ID заявления уже занят");}if(app.phase()!=Phase.OPEN||app.revision()!=1||!app.sponsors().isEmpty()||!app.terms().equals(state.board().terms(app.town())))throw new IllegalArgumentException("Условия подачи изменились");var apps=new HashMap<>(state.board().applications());apps.put(app.id(),app);return change(state,state.records(),state.board().policies(),apps,state.board().history());}
    public static Application current(State state,UUID id,long revision){var a=state.board().applications().get(id);if(a==null||a.revision()!=revision||a.phase()!=Phase.OPEN)throw new IllegalArgumentException("Заявление изменилось или уже рассмотрено");return a;}
    public static State sponsor(State state,UUID id,long revision,Sponsor sponsor,boolean remove){var a=current(state,id,revision);if(a.applicant().equals(sponsor.resident()))throw new IllegalArgumentException("Нельзя поручиться за себя");var sponsors=new HashMap<>(a.sponsors());if(remove){if(sponsors.remove(sponsor.resident())==null)return state;}else{if(sponsors.containsKey(sponsor.resident()))return state;sponsors.put(sponsor.resident(),sponsor);}var apps=new HashMap<>(state.board().applications());apps.put(id,a.support(sponsors));return change(state,state.records(),state.board().policies(),apps,state.board().history());}
    public static List<String> blockers(Application a,Set<UUID> eligible,boolean registered,boolean member,boolean mayor,long now){var result=new ArrayList<String>();if(!registered)result.add("Игрок больше не зарегистрирован на сервере");if(a.desired()!=CitizenshipStatus.HONORARY&&!member)result.add("Сначала игрок должен вступить в город через Towny");if(mayor&&a.desired()==CitizenshipStatus.TEMPORARY)result.add("Мэр должен оставаться гражданином или почётным гражданином");if(a.terms().minimumDays()>0){if(a.registeredAt()==0)result.add("Не подтверждена дата знакомства с сервером");else{long due=Math.addExact(a.registeredAt(),Math.multiplyExact((long)a.terms().minimumDays(),DAY));if(now<due)result.add("Срок знакомства с сервером ещё не достиг "+a.terms().minimumDays()+" дн.");}}long count=a.sponsors().keySet().stream().filter(eligible::contains).count();if(count<a.terms().sponsors())result.add("Действующие поручители: "+count+"/"+a.terms().sponsors());return List.copyOf(result);}
    private static List<Change> history(State state,CitizenshipRecord record,UUID id,UUID actor,String name,UUID application){var before=state.record(record.town(),record.resident());var history=new ArrayList<>(state.board().history());history.add(new Change(id,record.town(),record.resident(),before==null?"DEFAULT":before.status().name(),record.status().name(),actor,name,record.changedAt(),record.reason(),application));while(history.size()>10000)history.remove(0);return List.copyOf(history);}
    public static State record(State state,CitizenshipRecord record,UUID actor,String name){var records=new HashMap<>(state.records());records.put(record.key(),record);return change(state,records,state.board().policies(),state.board().applications(),history(state,record,UUID.randomUUID(),actor,name,null));}
    public static State decide(State state,UUID id,long revision,Phase phase,UUID actor,String name,String reason,long now,Set<UUID> eligible,boolean registered,boolean member,boolean mayor){var a=current(state,id,revision);if(phase==Phase.WITHDRAWN&&!a.applicant().equals(actor))throw new IllegalArgumentException("Отзывает заявление только его автор");if(phase==Phase.APPROVED){var errors=blockers(a,eligible,registered,member,mayor,now);if(!errors.isEmpty())throw new IllegalArgumentException(String.join("; ",errors));}var apps=new HashMap<>(state.board().applications());apps.put(id,a.close(phase,actor,name,reason,now));if(phase!=Phase.APPROVED)return change(state,state.records(),state.board().policies(),apps,state.board().history());long expires=a.desired()==CitizenshipStatus.TEMPORARY?Math.addExact(now,Math.multiplyExact((long)a.days(),DAY)):0;var record=new CitizenshipRecord(a.town(),a.applicant(),a.desired(),expires,now,actor.toString(),reason);var records=new HashMap<>(state.records());records.put(record.key(),record);return change(state,records,state.board().policies(),apps,history(state,record,id,actor,name,id));}
}
